  if (rank === "R1") return `Subciclo R1 \xB7 ${frac}`;
  if (rank === "R2") return `Ciclo R2 \xB7 ${frac}`;
  if (rank === "R3") return `Ciclo R3 \xB7 ${frac}`;
  if (rank === "R4") return `Ciclo R4 \xB7 ${frac}`;
