  inputInvite.id = "lan-input-invite-link";
  inputInvite.rows = 2;
  inputInvite.autocomplete = "off";
  inputInvite.placeholder = "http://10.x.x.x:3738/join/req_\u2026";
  inputInvite.style.marginTop = "6px";
  prefillBundledWardInviteInput2(inputInvite);
